function guvenBadge(guven){
  if(!guven) return "";
  const etiket = {yüksek:"yeterli veri", orta:"orta veri", düşük:"az veri", yetersiz:"yetersiz veri", yok:"veri yok"}[guven] || guven;   // Code.gs v2.23 ile aynı dil
  const renkler = {yüksek:["#DCFCE7","#166534"], orta:["#DBEAFE","#1E40AF"], düşük:["#FEF3C7","#92400E"], yetersiz:["#F1F5F9","#475569"], yok:["#F1F5F9","#475569"]};
  const r = renkler[guven] || renkler.yetersiz;
  return `<span style="display:inline-block;font-size:9px;font-weight:800;padding:2px 7px;border-radius:7px;margin-left:5px;background:${r[0]};color:${r[1]};white-space:nowrap;">${etiket}</span>`;
}

// Veli telefonunu WhatsApp'ın beklediği biçime (ülke koduyla, yalnızca rakam) getirir.
// - Girdi "+" ile başlıyorsa ya da rakamlara çevrilince "00" ile başlıyorsa, kullanıcının zaten bir ülke
//   kodu yazdığı kabul edilir: yalnızca uluslararası erişim öneki "00" atılır, başka dokunulmaz. (Eski
//   sürüm bunu ayırt etmiyordu: "0090 532..." gibi baştan ülke koduyla yazılmış bir Türkiye numarasını
//   "900905321234567" gibi yanlış bir sonuca, "+49 170..." gibi yurt dışı bir numarayı da başına 90
//   ekleyerek bozuyordu.)
// - Aksi halde yurt içi (Türkiye) numara varsayılır: baştaki tek "0" (varsa) atılır, "90" eklenir
//   ("90" ile zaten başlıyorsa tekrar eklenmez).
function normalizeTelefon(telefon){
  let raw = String(telefon||"").trim();
  let digits = raw.replace(/[^0-9]/g,"");
  if(raw.indexOf("+")===0 || digits.indexOf("00")===0){
    return digits.replace(/^00/,"");
  }
  digits = digits.replace(/^0/,"");
  if(digits.indexOf("90")===0 && digits.length>10) return digits;
  return "90"+digits;
}

// ================= WHATSAPP: MASAÜSTÜ UYGULAMASI / WHATSAPP WEB (v3.3) =================
// Tercih tarayıcıda hatırlanır; varsayılan masaüstü uygulaması. Masaüstü: whatsapp:// bağlantısı doğrudan
// WhatsApp uygulamasında ilgili sohbeti mesaj hazır yazılı olarak açar (sayfadan ayrılmadan; boş sekme açılmaz).
// Chrome/Edge ilk seferde "WhatsApp açılsın mı?" diye sorar: "Her zaman izin ver" işaretlenirse bir daha sormaz.
// Web: eskisi gibi web.whatsapp.com, hep aynı sekmede ("whatsappSekmesi").
const WA_TERCIH_ANAHTARI = "fhUltraMat_whatsappHedefi";
function whatsappHedefi(){
  try{ return localStorage.getItem(WA_TERCIH_ANAHTARI) === "web" ? "web" : "masaustu"; }catch(e){ return "masaustu"; }
}
function whatsappHedefiniKaydet(hedef){ try{ localStorage.setItem(WA_TERCIH_ANAHTARI, hedef); }catch(e){} }
function whatsappAdresi(telefon, mesaj, hedef){
  // Mesaj boşsa yalnızca sohbet açılır (karne yapıştırılmadan önce doğru veliye geçmek için).
  let parametre = "phone=" + telefon + (mesaj ? ("&text=" + encodeURIComponent(mesaj)) : "");
  return (hedef || whatsappHedefi()) === "web" ? ("https://web.whatsapp.com/send?" + parametre) : ("whatsapp://send?" + parametre);
}
function whatsappAc(telefon, mesaj){
  let adres = whatsappAdresi(telefon, mesaj);
  if(whatsappHedefi() === "web"){ window.open(adres, "whatsappSekmesi"); return; }
  // Uygulama bağlantısı gizli bir bağlantıya tıklatılarak açılır: sayfa yerinde kalır, yeni sekme açılmaz.
  let a = document.createElement("a");
  a.href = adres; a.style.display = "none";
  document.body.appendChild(a); a.click(); a.remove();
}
// Masaüstü modunda 2. ve 3. düğme de uygulamaya bağlıdır: karne panoya kopyalanır VE o velinin sohbeti öne gelir
// (yalnızca Ctrl+V + Enter kalır); son mesaj panoya değil doğrudan sohbetin yazı kutusuna gelir (yalnızca Enter).
// Web modunda eski davranış (panoya kopyala) aynen sürer: web.whatsapp.com her açılışta baştan yüklendiği için
// orada pano daha hızlıdır.
function dugmeEtiketi(tur){
  let m = whatsappHedefi() === "masaustu";
  if(tur === "karne") return m ? "2. Karneyi Kopyala + Sohbeti Aç" : "2. Karneyi Kopyala";
  return m ? "3. Son Mesajı Gönder" : "3. Son Mesajı Kopyala";
}
function dugmeEtiketleriniGuncelle(){
  document.querySelectorAll("button[data-etiket]").forEach(function(b){ if(!b.disabled || b.textContent.indexOf("⏳") === -1) b.textContent = dugmeEtiketi(b.getAttribute("data-etiket")); });
}
function whatsappSeciciniKur(){
  let kap = document.getElementById("waHedefSecici");
  if(!kap) return;
  let ciz = function(){
    let h = whatsappHedefi();
    kap.querySelectorAll("button").forEach(function(b){ b.setAttribute("aria-pressed", String(b.getAttribute("data-hedef") === h)); });
    document.getElementById("waHedefIpucu").textContent = h === "masaustu"
      ? "Mesajlar ve karne sohbeti WhatsApp masaüstü uygulamasında açılır; sana yalnızca Enter (karnede Ctrl+V + Enter) kalır. Tarayıcı ilk seferde izin sorarsa \"Her zaman izin ver\"i işaretle."
      : "Mesajlar tarayıcıda WhatsApp Web sekmesinde açılır.";
  };
  kap.querySelectorAll("button").forEach(function(b){ b.onclick = function(){ whatsappHedefiniKaydet(b.getAttribute("data-hedef")); ciz(); dugmeEtiketleriniGuncelle(); }; });
  ciz();
}
document.addEventListener("DOMContentLoaded", whatsappSeciciniKur);

// Kaba bir "bu numara açıkça hatalı/eksik girilmiş" kontrolü (tam biçim doğrulaması değil). Ogrenciler
// sayfasına "1234" gibi bir şey yazılmışsa WhatsApp düğmelerini kilitler ve öğretmeni uyarır — eskiden
// bu durumda uyarı yoktu, düğmeler sessizce yanlış bir numarayla WhatsApp'ı açardı.
function telefonCokKisaMi(telefon){
  let digits = String(telefon||"").replace(/[^0-9]/g,"");
  return digits.length > 0 && digits.length < 7;
}

function performansRengi(yuzde){
  if(yuzde>=90) return "#16A34A";
  if(yuzde>50) return "#2563EB";
  return "#DC2626";
}

// Genel başarı rozetinin rengi artık YAZAN İFADEYE göre değişir (Code.gs → basariEtiketiHesapla:
// Mükemmel/Çok İyi/İyi/Geliştirilmeli — sabit 4 etiket, sınıf 7-8 için puan eşiği 90/70/50, 5-6 için
// 67.5/52.5/37.5). Kartın geri kalanında zaten kurulu renk diliyle aynı sırayı izler: en iyi = yeşil
// (performansRengi'nin %90+ yeşiliyle aynı ton), sonra mavi (performansRengi'nin >%50 mavisiyle aynı),
// sonra amber (sayfadaki diğer "dikkat" kutularıyla aynı — .uyari, .satirDurum.uyari, .veriSorunKutu.
// sadeceUyari), en düşük = kırmızı (performansRengi'nin %50-altı kırmızısıyla ve zayıf alt konu
// vurgusuyla — .altSatir.zayif — aynı). Yeni bir etiket ileride eklenirse (bu dört isim dışında bir şey
// gelirse) nötr gri kullanılır, kart bozulmaz.
function basariRenkleri(etiket){
  const RENK = {
    "Mükemmel":       { bg: "#ECFDF5", fg: "#16A34A" },
    "Çok İyi":        { bg: "#EFF6FF", fg: "#2563EB" },
    "İyi":            { bg: "#FFFBEB", fg: "#92400E" },
    "Geliştirilmeli": { bg: "#FEF2F2", fg: "#B91C1C" }
  };
  return RENK[etiket] || { bg: "#F1F5F9", fg: "#475569" };
}

function konuIkon(konu){
  konu = (konu||"").toLowerCase();
  if(konu.includes("üslü")) return "aⁿ";
  if(konu.includes("karekök")) return "√x";
  if(konu.includes("çarpan")) return "123";
  if(konu.includes("cebir")) return "x+y";
  if(konu.includes("olasılık")) return "%";
  if(konu.includes("doğrusal")) return "y=x";
  if(konu.includes("üçgen")) return "△";
  if(konu.includes("dönüşüm")) return "⟳";
  if(konu.includes("cisim")) return "⬡";
  if(konu.includes("eşitsizlik")) return "≠";
  if(konu.includes("eğim")) return "∕";
  if(konu.includes("geometri")) return "∟";
  return "Σ";
}

