// fetch'e yerleşik bir zaman aşımı yok; sunucu yanıt vermezse ekran süresiz "Yükleniyor..."
// durumunda kalmasın diye AbortController ile bunu ekliyoruz (index.html ile aynı desen).
async function fetchZamanAsimli(url, zamanAsimiMs, secenek){
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), zamanAsimiMs);
  try{
    const response = await fetch(url, Object.assign({}, secenek || {}, { signal: controller.signal }));
    clearTimeout(timeoutId);
    return response;
  }catch(err){
    clearTimeout(timeoutId);
    if(err.name === "AbortError"){
      const zamanAsimiHatasi = new Error("ZAMAN_ASIMI");
      zamanAsimiHatasi.isTimeout = true;
      throw zamanAsimiHatasi;
    }
    throw err;
  }
}

// v3.48 (Code.gs v2.36) — Sunucuya giden bütün istekler POST ile gider; öğretmen anahtarı adres satırında (URL)
// görünmez, Google'ın istek kayıtlarına ve tarayıcı geçmişine düşmez. Gövde düz metin (text/plain) JSON'dur:
// tarayıcı ön kontrol (CORS preflight) isteği yapmaz, Apps Script doğrudan yanıt verir.
// Sayfa bilgisayardan dosya olarak (file://) açılmışsa ve POST engellenirse bir kez eski GET yoluyla denenir.
async function apiIstek(parametreler, zamanAsimiMs){
  let govde = JSON.stringify(Object.assign({ kanal: "istek" }, parametreler));
  try{
    return await fetchZamanAsimli(API_URL, zamanAsimiMs, { method: "POST", headers: { "Content-Type": "text/plain;charset=UTF-8" }, body: govde });
  }catch(err){
    if(location.protocol !== "file:" || (err && err.isTimeout)) throw err;
    let q = new URLSearchParams();
    Object.keys(parametreler).forEach(function(k){ let v = parametreler[k]; if(v !== undefined && v !== null) q.set(k, Array.isArray(v) ? v.join(",") : String(v)); });
    return fetchZamanAsimli(`${API_URL}?${q.toString()}`, zamanAsimiMs);
  }
}

