// İMZA: dosyanın İÇİNDE DEĞİL. Sayfa GitHub'da herkese açık olduğu için imza gömülmez; öğretmen imza görselini
// bir kez seçer, beyaz zemini temizlenip YALNIZCA o bilgisayarın tarayıcısında saklanır (localStorage).
// İmza yoksa belgede el yazısı yazı tipiyle "Fatih Hoca" yazılır.
const IMZA_ANAHTARI = "fhUltraMat_imza_v4";   // v3.25: ıslak imza görünümü — mavi dolma kalem mürekkebi, hafif kalın çizgi
function imzaGorseli(){ try{ return localStorage.getItem(IMZA_ANAHTARI) || ""; }catch(e){ return ""; } }
function imzaHtml(sinif){
  let g = imzaGorseli();
  return g ? `<img class="${sinif}" src="${g}" alt="İmza">` : `<span class="${sinif} odImzaYedek">Fatih Hoca</span>`;
}
// Veliye giden karnede de öğretmenin kendi (ıslak görünümlü) imzası kullanılır; seçilmemişse eski imza görseli.
function karneImzaHtml(){
  let g = imzaGorseli();
  return g ? `<div class="khImzaBlok"><img class="khImzaGorsel" src="${g}" alt="İmza"><b class="khImzaAd">Fatih KARYAĞDI</b><small class="khImzaUnvan">Matematik Öğretmeni</small></div>` : SIGNATURE_IMG;
}
function imzaDosyasiniIsle(dosya){
  return new Promise(function(coz, reddet){
    let okur = new FileReader();
    okur.onerror = reddet;
    okur.onload = function(){
      let img = new Image();
      img.onerror = reddet;
      img.onload = function(){
        let olcek = Math.min(1, 600 / img.width), w = Math.round(img.width * olcek), h = Math.round(img.height * olcek);
        let t = document.createElement("canvas"); t.width = w; t.height = h;
        let x = t.getContext("2d"); x.drawImage(img, 0, 0, w, h);
        let v = x.getImageData(0, 0, w, h), d = v.data, minX = w, minY = h, maxX = 0, maxY = 0;
        // 1) beyaz → saydam: mürekkep yoğunluğu (alfa) parlaklıktan
        let alfa = new Float32Array(w * h);
        for(let i = 0, p = 0; i < d.length; i += 4, p++){ let l = (d[i] + d[i+1] + d[i+2]) / 3; alfa[p] = Math.max(0, Math.min(1, (235 - l) / 180)); }
        // 2) ıslak mürekkep taklidi — (a) çizgiyi kalem basıncı gibi kalınlaştır, (b) mürekkebin kâğıda hafif yayılması
        //    (yumuşak hale), (c) çekirdekte koyu, kenarda açık mavi, (d) düşük frekanslı yoğunluk dalgalanması + kâğıt dokusu.
        let yay = function(src, yaricap, carpan){
          let out = new Float32Array(w * h);
          for(let yy = 0; yy < h; yy++) for(let xx = 0; xx < w; xx++){
            let m = 0;
            let Rn = Math.ceil(yaricap);
            for(let dy = -Rn; dy <= Rn; dy++) for(let dx = -Rn; dx <= Rn; dx++){
              let X = xx + dx, Y = yy + dy; if(X < 0 || Y < 0 || X >= w || Y >= h) continue;
              let uz = Math.sqrt(dx * dx + dy * dy); if(uz > yaricap + 0.01) continue;
              let k = src[Y * w + X] * (1 - uz / (yaricap + 1) * carpan); if(k > m) m = k;
            }
            out[yy * w + xx] = m;
          }
          return out;
        };
        let bulanik = function(src){   // 3x3 ortalama, iki kez: kâğıda yayılma
          let a1 = new Float32Array(w * h), a2 = new Float32Array(w * h);
          [[src, a1], [a1, a2]].forEach(function(ci){
            let g = ci[0], c = ci[1];
            for(let yy = 0; yy < h; yy++) for(let xx = 0; xx < w; xx++){
              let t = 0, n = 0;
              for(let dy = -1; dy <= 1; dy++) for(let dx = -1; dx <= 1; dx++){ let X = xx + dx, Y = yy + dy; if(X < 0 || Y < 0 || X >= w || Y >= h) continue; t += g[Y * w + X]; n++; }
              c[yy * w + xx] = t / n;
            }
          });
          return a2;
        };
        let govde = yay(alfa, 1.6, 0.35);            // kalem basıncı: çizgi ~%60 kalınlaşır
        let hale = bulanik(govde);                   // mürekkebin kâğıda yayılması
        let tohum = 7, rnd = function(){ tohum = (tohum * 16807) % 2147483647; return tohum / 2147483647; };
        for(let i = 0, p = 0; i < d.length; i += 4, p++){
          let y = Math.floor(p / w), x0 = p % w;
          let cekirdek = Math.min(1, govde[p] * 1.25), a = Math.max(cekirdek, hale[p] * 0.55);
          let dalga = 0.86 + 0.14 * (0.5 + 0.5 * Math.sin(x0 * 0.045 + Math.cos(y * 0.07) * 2.1));   // basınç/yoğunluk dalgası
          let doku = 0.93 + 0.07 * rnd();                                                            // kâğıt lifi
          let koyu = Math.min(1, cekirdek * dalga);                                                  // 1 = çekirdek, 0 = kenar
          d[i]   = Math.round(12 + (58 - 12) * (1 - koyu));     // çekirdek #0C1F6E → kenar #3A5BC4
          d[i+1] = Math.round(31 + (91 - 31) * (1 - koyu));
          d[i+2] = Math.round(110 + (196 - 110) * (1 - koyu));
          d[i+3] = Math.round(Math.min(1, a * dalga * doku) * 255);
          if(d[i+3] > 40){ if(x0 < minX) minX = x0; if(x0 > maxX) maxX = x0; if(y < minY) minY = y; if(y > maxY) maxY = y; }
        }
        x.putImageData(v, 0, 0);
        if(maxX <= minX){ reddet(new Error("Görselde imza bulunamadı")); return; }
        let k = document.createElement("canvas"); k.width = maxX - minX + 1; k.height = maxY - minY + 1;
        k.getContext("2d").drawImage(t, minX, minY, k.width, k.height, 0, 0, k.width, k.height);
        coz(k.toDataURL("image/png"));
      };
      img.src = okur.result;
    };
    okur.readAsDataURL(dosya);
  });
}

// Sayı ekleri: "5'ten 2'ye", "9'dan 3'e", "12,67 nete" …
function yuzdeEkSade(n, hal){
  let x = Math.abs(Math.round(Number(n)));
  let k = x === 0 ? "sıfır" : x % 100 === 0 ? "yüz" : x % 10 === 0 ? {10:"on",20:"yirmi",30:"otuz",40:"kırk",50:"elli",60:"altmış",70:"yetmiş",80:"seksen",90:"doksan"}[x % 100] : ["","bir","iki","üç","dört","beş","altı","yedi","sekiz","dokuz"][x % 10];
  let unlu = (k.match(/[aeıioöuü](?=[^aeıioöuü]*$)/) || ["e"])[0], kalin = "aıou".indexOf(unlu) !== -1, son = k.slice(-1);
  let unluBiter = "aeıioöuü".indexOf(son) !== -1, sert = "fstkçşhp".indexOf(son) !== -1;
  if(hal === "e") return n + "'" + (unluBiter ? "y" : "") + (kalin ? "a" : "e");
  return n + "'" + (sert ? "t" : "d") + (kalin ? "a" : "e") + "n";
}

function odulAdaylari(liste){
  let sinav = (liste[0] && liste[0].sinav) || "";
  let N = function(x){ let v = Number(x); return x === null || x === undefined || isNaN(v) ? null : v; };
  let fmt = function(x){ return String(Math.round(x * 100) / 100).replace(".", ","); };
  let olcutler = [];
  // 🏅 Kişisel rekor
  olcutler.push({ id: "rekor", ad: "🏅 Kendi Rekorunu Kıranlar", aday: liste.filter(function(o){ let n = N(o.net), r = N(o.oncekiEnYuksekNet); return n !== null && r !== null && n > r; })
    .map(function(o){ return { o: o, detay: `${fmt(N(o.oncekiEnYuksekNet))} → ${fmt(N(o.net))} net`, neden: `kendi rekorunu kırarak ${fmt(N(o.net))} nete ulaştı`, nedenAd: `kendi rekorunu kırarak ${fmt(N(o.net))} nete ulaşması`, puan: N(o.net) - N(o.oncekiEnYuksekNet) }; }) });
  // 📈 En çok net artıran
  olcutler.push({ id: "artis", ad: "📈 Netini En Çok Artıranlar", aday: liste.filter(function(o){ let n = N(o.net), p = N(o.oncekiNet); return n !== null && p !== null && n - p >= 1; })
    .map(function(o){ let d = N(o.net) - N(o.oncekiNet); return { o: o, detay: `+${fmt(d)} net (${fmt(N(o.oncekiNet))} → ${fmt(N(o.net))})`, neden: `bir önceki sınava göre netini ${fmt(d)} artırdı`, nedenAd: `bir önceki sınava göre netini ${fmt(d)} artırması`, puan: d }; }) });
  // 🛡️ Yanlışlarını azaltan
  olcutler.push({ id: "dikkat", ad: "🛡️ Yanlışlarını En Çok Azaltanlar", aday: liste.filter(function(o){ let a = N(o.oncekiYanlis), b = N(o.yanlis); return a !== null && b !== null && a - b >= 2; })
    .map(function(o){ let a = N(o.oncekiYanlis), b = N(o.yanlis); return { o: o, detay: `${a} → ${b} yanlış`, neden: `yanlış sayısını ${yuzdeEkSade(a, "den")} ${yuzdeEkSade(b, "e")} indirdi`, nedenAd: `yanlış sayısını ${yuzdeEkSade(a, "den")} ${yuzdeEkSade(b, "e")} indirmesi`, puan: a - b }; }) });
  // 🧩 Bir içerik çerçevesinin bütün soruları
  olcutler.push({ id: "icerik", ad: "🧩 Bir İçeriğin Bütün Sorularını Doğru Yapanlar", aday: liste.map(function(o){
      let tam = (o.konular || []).filter(function(k){ return (k.soruSayisi || 0) >= 2 && k.dogruSayisi === k.soruSayisi; }).sort(function(a, b){ return b.soruSayisi - a.soruSayisi; });
      return tam.length ? { o: o, detay: tam.map(function(k){ return k.konu; }).slice(0, 2).join(", ") + (tam.length > 2 ? " …" : ""), neden: `${tam[0].konu} konusundaki bütün soruları doğru yaptı`, nedenAd: `${tam[0].konu} konusundaki bütün soruları doğru yanıtlaması`, puan: tam.length } : null;
    }).filter(Boolean) });
  // 🎯 Sıfır yanlış
  olcutler.push({ id: "sifir", ad: "🎯 Hiç Yanlış Yapmayanlar", aday: liste.filter(function(o){ let t = (N(o.dogru) || 0) + (N(o.yanlis) || 0) + (N(o.bos) || 0); return N(o.yanlis) === 0 && t && N(o.dogru) >= t * 0.25; })
    .map(function(o){ return { o: o, detay: `${o.dogru} doğru, 0 yanlış`, neden: `hiç yanlış yapmadan ${o.dogru} soruyu doğru çözdü`, nedenAd: `hiç yanlış yapmadan ${o.dogru} soruyu doğru çözmesi`, puan: N(o.dogru) }; }) });
  olcutler.forEach(function(c){ c.aday.sort(function(a, b){ return b.puan - a.puan; }); c.aday = c.aday.slice(0, 6); c.sinav = sinav; });
  return olcutler;
}

/** v3.45 — Bir öğrencinin ödül kayıtları: ad + şube ile eşleşir (aynı adlı iki öğrencinin ödülleri karışmasın).
 *  Eski kayıtlarda şube 10 karakterle kısaltılmış olabilir; şubesi boş kayıt eski düzendeki gibi ada göre sayılır. */
function subeEslesir(kayitSube, sube){
  let a = String(kayitSube || "").trim().toLocaleLowerCase("tr"), b = String(sube || "").trim().toLocaleLowerCase("tr");
  if(!a || !b) return true;
  return a === b || (a.length === 10 && b.indexOf(a) === 0);
}
function odulKayitlari(o){
  return (odulGecmisi[String(o && o.isim || "").trim()] || []).filter(function(r){ return subeEslesir(r.sube, o && o.sube); });
}
function odulGecmisOzeti(o){
  let g = odulKayitlari(o);
  if(!g.length) return `<span class="odIlk">✨ ilk ödülü olur</span>`;
  let son = g[g.length - 1], gun = son.zaman ? Math.floor((Date.now() - new Date(son.zaman).getTime()) / 86400000) : null;
  return `<span class="odGecmis" title="${htmlKacis(g.map(function(x){ return x.tur + " (" + (x.sinavID || "") + ")"; }).join(", "))}">${g.length} ödül · son: ${gun === null ? "?" : gun === 0 ? "bugün" : gun + " gün önce"}</span>`;
}

function odulOnerileriHtml(A, liste){
  let olcutler = odulAdaylari(liste);
  let kupSec = KUPON_TURLERI.map(function(k, i){ return `<option value="${i}">${htmlKacis(k.ad)}</option>`; }).join("") + `<option value="ozel">Özel Kupon…</option>`;
  let bolumler = olcutler.map(function(c){
    let satirHtml = c.aday.map(function(a, i){
      let ad = String(a.o.isim || "").trim();
      return `<div class="odSatir" data-olcut="${c.id}" data-i="${i}">
        <div class="odKim"><b>${htmlKacis(ad)}</b> <span class="odDetay">${htmlKacis(a.detay)}</span> ${odulGecmisOzeti(a.o)}</div>
        <div class="odDugmeler">
          <button type="button" class="odBtn" data-is="belge">🏆 Belge</button>
          <span class="odKupon"><select class="odKuponSec" aria-label="Kupon türü">${kupSec}</select><button type="button" class="odBtn" data-is="kupon">🎟️ Kupon</button></span>
          <button type="button" class="odBtn odTebrik" data-is="tebrik">💬 Tebrik</button>
        </div>
        <div class="odDurum" role="status" aria-live="polite"></div>
      </div>`;
    });
    let satir = satirHtml.slice(0, 3).join("") + (satirHtml.length > 3 ? `<details class="odDaha"><summary>${satirHtml.length - 3} aday daha</summary>${satirHtml.slice(3).join("")}</details>` : "");
    return `<div class="odOlcut"><div class="odOlcutAd">${c.ad} <span class="odSay">${c.aday.length || "aday yok"}</span></div>${satir}</div>`;
  }).join("");
  return `<div class="anKart" id="odulKart">
    <div class="anBaslik"><h3>🎖️ Ödül Önerileri</h3><small>Yalnızca sen görürsün</small></div>
    <div class="odImzaAyar" id="odImzaAyar">${imzaAyarIcerik()}</div>
    <div class="istAciklama">Ödül gelişime ve çabaya bağlı olsun, sıralamaya değil. Bu sınav hangi ölçütü ödüllendireceğine sen karar ver; öğrenciler önceden bilmesin ki ödül gerçekten sürpriz olsun. "✨ ilk ödülü olur" işaretli öğrencilere öncelik verebilirsin. Verdiğin her ödül "Oduller" sayfasına kaydedilir.</div>
    ${bolumler}
  </div>`;
}

async function odulKaydetSunucu(o, tur, neden){
  let anahtar = ogretmenAnahtari();
  let q = { odulKaydet: "1", anahtar: anahtar, odulIsim: String(o.isim || "").trim(), odulSube: String(o.sube || ""), odulSinav: o.sinavID || "", odulTur: tur, odulNeden: neden };
  try{
    let res = await apiIstek(q, 15000);
    let d = await jsonOku(res);
    if(d && d.ok){
      let ad = String(o.isim || "").trim();
      (odulGecmisi[ad] = odulGecmisi[ad] || []).push({ zaman: new Date().toISOString(), sinavID: o.sinavID || "", tur: tur, neden: neden, sube: String(o.sube || "") });
      return true;
    }
  }catch(e){ console.warn("[UltraMat] Ödül kaydedilemedi:", e); }
  return false;
}


