function odulYazdir(html, baslik){
  let alan = document.getElementById("odulYazdirmaAlani");
  if(!alan){ alan = document.createElement("div"); alan.id = "odulYazdirmaAlani"; alan.className = "odulYazdirma"; document.body.appendChild(alan); }
  alan.innerHTML = html;
  let eski = document.title; document.title = baslik.replace(/\s+/g, "-");
  document.body.classList.add("odulYazdiriliyor");
  let bitir = function(){ document.body.classList.remove("odulYazdiriliyor"); document.title = eski; window.removeEventListener("afterprint", bitir); };
  window.addEventListener("afterprint", bitir);
  let bekle = Array.from(alan.querySelectorAll("img")).map(function(img){ return img.complete ? null : new Promise(function(c){ img.onload = img.onerror = c; setTimeout(c, 2000); }); });
  // Yazı tiplerinin hem Latin hem Türkçe (latin-ext) alt kümeleri yazdırmadan ÖNCE yüklensin (ş, ğ, ı, İ …)
  if(document.fonts && document.fonts.load) bekle.push(Promise.all(["900 20px OdPlayfair", "700 20px OdPlayfair", "400 20px OdPlayfair", "400 20px OdScript", "900 20px OdNunito", "800 20px OdNunito"]
    .map(function(f){ return document.fonts.load(f, "AaBbĞğŞşİıÖöÜüÇç").catch(function(){}); })));
  Promise.all(bekle).then(function(){ window.print(); });
}
function odulTebrikMesaji(o, neden, sinav){
  let ilkAd = String(o.isim || "").trim().split(/\s+/)[0] || "Öğrencimiz";
  let selam = o.veliHitap ? `Merhaba ${o.veliHitap},` : "Merhaba,";
  return `${selam}\n\n${tamlayanEki(ilkAd)} ${sinav} sınavındaki çalışmasını tebrik etmek istedim: *${neden}.* `
    + `Bu, düzenli çalışmasının güzel bir sonucu. Emeği için kendisini kutluyorum; bu gayretle devam etmesini dilerim.\n\n— Fatih Hoca ${IMZA_EMOJI}`;
}

