function imzaAyariBagla(kap){
  let alan = kap.querySelector("#odImzaAyar"); if(!alan) return;
  let dosya = alan.querySelector("#odImzaDosya");
  alan.querySelector("#odImzaDegis").onclick = function(){ dosya.click(); };
  let sil = alan.querySelector("#odImzaSil");
  if(sil) sil.onclick = function(){ try{ localStorage.removeItem(IMZA_ANAHTARI); }catch(e){} alan.innerHTML = imzaAyarIcerik(); imzaAyariBagla(kap); };
  dosya.onchange = async function(){
    let f = dosya.files && dosya.files[0]; if(!f) return;
    try{ let veri = await imzaDosyasiniIsle(f); localStorage.setItem(IMZA_ANAHTARI, veri); alan.innerHTML = imzaAyarIcerik(); imzaAyariBagla(kap); }
    catch(e){ alert("İmza görseli işlenemedi: " + (e && e.message ? e.message : e)); }
  };
}

