function onurDalSvg(ters){
  let yap = "";
  for(let k = 0; k < 6; k++){
    let x = 4 + k * 3.4, y = 7 + Math.sin(k / 5 * Math.PI) * -1.2;
    yap += `<path d="M0 0 Q2.2 -3.6 0 -7.6 Q-2.2 -3.6 0 0Z" transform="translate(${x.toFixed(1)} ${y.toFixed(1)}) rotate(${(-55 + k * 4)})" fill="url(#onDalG)"/>`;
    yap += `<path d="M0 0 Q2.2 -3.6 0 -7.6 Q-2.2 -3.6 0 0Z" transform="translate(${x.toFixed(1)} ${y.toFixed(1)}) rotate(${(125 - k * 4)})" fill="url(#onDalG)"/>`;
  }
  return `<svg class="onDal" viewBox="0 0 28 14" aria-hidden="true" ${ters ? 'style="transform:scaleX(-1)"' : ""}><defs><linearGradient id="onDalG" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#E9CB7A"/><stop offset="1" stop-color="#8A6414"/></linearGradient></defs>
    <path d="M2 7.4 Q14 5.4 25 7" fill="none" stroke="#8A6414" stroke-width=".7" stroke-linecap="round"/>${yap}</svg>`;
}
