let donemBilgisi = null, egitimYili = "";
function onurVerildiMi(o, donemAd){
  return odulKayitlari(o).some(function(r){ return String(r.tur).indexOf("Onur Belgesi") === 0 && String(r.neden || "").indexOf(donemAd) === 0; });
}
function onurNedenMetni(oneri){ return oneri.donemAd + " · " + oneri.onurlar.map(function(x){ return x.ad; }).join(", "); }
function onurYillikKur(liste){
  ["onurKart", "yillikKart"].forEach(function(id){ let e = document.getElementById(id); if(e) e.remove(); });
  // --- Onur Belgeleri ---
  let adaylar = liste.filter(function(o){ return o.onurOnerisi; });
  let donemAd = donemBilgisi ? donemBilgisi.ad : "Bu dönem";
  let kart = document.createElement("div"); kart.className = "anKart"; kart.id = "onurKart";
  let satirlar = adaylar.map(function(o){
    let i = liste.indexOf(o), verildi = onurVerildiMi(o, o.onurOnerisi.donemAd);
    return `<div class="onSatir"><div class="onSatirAd"><b>${htmlKacis(o.isim)}</b>${verildi ? ` <span class="onVerildi">✓ verildi</span>` : ""}</div>
      <div class="onCipler">${o.onurOnerisi.onurlar.map(function(x){ return `<span class="onCip" title="${htmlKacis(x.aciklama)}"><i>${onurMiniIkon(x.id)}</i>${htmlKacis(x.ad)}<small>${htmlKacis(x.aciklama)}</small></span>`; }).join("")}</div>
      <button type="button" class="odBtn onYazBtn" data-i="${i}">🖨 Belge</button></div>`;
  }).join("");
  kart.innerHTML = `<div class="anBaslik"><h3>📜 Onur Belgeleri · ${htmlKacis(donemAd)}</h3><small>${adaylar.length ? adaylar.length + " öğrenci onur kazandı" : "henüz onur kazanan yok"}</small></div>
    ${adaylar.length ? satirlar + `<div style="margin-top:10px;display:flex;gap:8px;flex-wrap:wrap"><button type="button" class="odBtn" id="onurHepsiBtn">🖨 Hepsini Yazdır (${adaylar.length})</button></div>` : ""}
    <div class="anNot">Onur Belgesi tek bir sınavı değil, dönem boyunca gösterilen tutumu onurlandırır. Ölçütler (dönem içinde): 🎯 Sözünün Eri en az 3 meydan okuma başarısı · 🏔️ Zirveci yıl hedefine ulaştı · 🤝 Mentor · 📅 İstikrar dönemin bütün sınavları (en az 4) · 📈 Yükseliş son 3 sınav ortalaması ilk 3'ünkinden en az 2 net yüksek · 🧭 Kâşif en az 3 yeni bayrak (en az 4 soruyla). Yazdırılan belge Oduller sayfasına kaydedilir ve öğrencinin dönem kartında madalya olarak görünür.</div>
    <div class="raporIpucu" id="onurDurum" role="status" aria-live="polite"></div>`;
  bolumeYerlestir("yuvaOnur", "onurBelgeleri", "📜", "Onur Belgeleri",
    adaylar.length ? { metin: `${donemAd} · ${adaylar.length} öğrenci`, tur: "iyi" } : `${donemAd} · henüz yok`, kart, false);
  let yazdir = async function(secilen){
    let n0 = 0; Object.keys(odulGecmisi || {}).forEach(function(k){ n0 += (odulGecmisi[k] || []).length; });
    let yil = new Date().getFullYear();
    let html = secilen.map(function(o, j){
      return onurBelgeHtml(o, o.onurOnerisi.onurlar, { ad: o.onurOnerisi.donemAd, yil: o.onurOnerisi.yil, belgeNo: "UM-" + yil + "-" + String(n0 + j + 1).padStart(4, "0") });
    }).join("");
    odulYazdir(html, secilen.length === 1 ? "Onur-Belgesi-" + adElYazisi(secilen[0].isim) : "Onur-Belgeleri-" + donemAd);
    let kaydedilen = 0;
    for(let o of secilen){ if(await odulKaydetSunucu(o, "Onur Belgesi", onurNedenMetni(o.onurOnerisi))) kaydedilen++; }
    onurYillikKur(liste);
    let d = document.getElementById("onurDurum"); if(d) d.textContent = kaydedilen === secilen.length ? `📜 ${kaydedilen} belge Oduller sayfasına kaydedildi.` : `⚠️ ${secilen.length - kaydedilen} belge kaydedilemedi (bağlantı).`;
  };
  kart.querySelectorAll(".onYazBtn").forEach(function(b){ b.onclick = function(){ yazdir([liste[Number(b.getAttribute("data-i"))]]); }; });
  let hepsi = document.getElementById("onurHepsiBtn"); if(hepsi) hepsi.onclick = function(){ yazdir(adaylar); };

  // --- Yıl Sonu Yıllığı ---
  let ogr = liste.filter(function(o){ return o.harita && o.harita.toplam; });
  if(!ogr.length) return;
  let subeler = Array.from(new Set(ogr.map(function(o){ return String(o.sube || "").trim(); }))).sort();
  let yk = document.createElement("div"); yk.className = "anKart"; yk.id = "yillikKart";
  let sinifDuzey = ogr[0].sinif || "";
  yk.innerHTML = `<div class="anBaslik"><h3>📖 Yıl Sonu Yıllığı</h3><small>kapak · sınıf sayfası · her öğrenciye bir sayfa (A4 dikey)</small></div>
    <div class="ykForm">
      <label>Şube <select id="ykSube">${subeler.map(function(s){ return `<option value="${htmlKacis(s)}">${htmlKacis(sinifDuzey + "-" + s)}</option>`; }).join("")}</select></label>
      <label class="ykNotEtiket">Fatih Hoca'nın Notu (sınıf sayfasında, imzanla)<textarea id="ykNot" rows="4" maxlength="600" placeholder="Sınıfına yıl sonu için birkaç cümle…"></textarea></label>
      <button type="button" class="odBtn" id="ykYazdir">🖨 Yıllığı Yazdır</button>
    </div>
    <div class="anNot">Yıllık, bu sınava kadarki bütün yılın verisiyle hazırlanır; yıl sonunda son sınavı seçerek yazdır. Öğrenci sayfalarında net, puan ya da sıra yok. Notun bu tarayıcıda şube başına saklanır.</div>`;
  bolumeYerlestir("yuvaYillik", "yillik", "📖", "Yıl Sonu Yıllığı", "Kapak · Sınıf Sayfası · Öğrenci Sayfaları", yk, false);
  let notAnahtar = function(){ return "fhUltraMat_yillikNot::" + sinifDuzey + "-" + document.getElementById("ykSube").value; };
  let notYukle = function(){ try{ document.getElementById("ykNot").value = localStorage.getItem(notAnahtar()) || ""; }catch(e){} };
  notYukle();
  document.getElementById("ykSube").onchange = notYukle;
  document.getElementById("ykNot").oninput = function(){ try{ localStorage.setItem(notAnahtar(), this.value); }catch(e){} };
  document.getElementById("ykYazdir").onclick = function(){
    let sube = document.getElementById("ykSube").value;
    let sec = ogr.filter(function(o){ return String(o.sube || "").trim() === sube; }).sort(function(a, b){ return adElYazisi(a.isim).localeCompare(adElYazisi(b.isim), "tr"); });
    yillikYazdir(sec, sinifDuzey + "-" + sube, document.getElementById("ykNot").value.trim());
  };
}
function onurMiniIkon(id){ return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${ONUR[id].ikon}</svg>`; }
function yillikYazdir(ogr, sinifAd, not){
  if(!ogr.length) return;
  // sınıf haritası: içerik başına bütün öğrencilerin havuzu
  let bolgeler = ogr[0].harita.bolgeler.map(function(b){ return { ad: b.ad, icerikler: b.icerikler.map(function(x){
    let d = 0, n = 0;
    ogr.forEach(function(o){ o.harita.bolgeler.forEach(function(bb){ bb.icerikler.forEach(function(y){ if(y.icerik === x.icerik){ d += y.d; n += y.n; } }); }); });
    let sev = !n ? "sis" : (d / n >= .9 && n >= 4 ? "usta" : d / n >= .7 ? "saglam" : d / n >= .5 ? "filiz" : "kesif");
    return { icerik: x.icerik, seviye: sev, d: d, n: n }; }) }; });
  let bayrak = {}, mentorlar = [];
  ogr.forEach(function(o){ o.harita.bolgeler.forEach(function(b){ b.icerikler.forEach(function(x){
    if(x.seviye === "saglam" || x.seviye === "usta") bayrak[x.icerik] = (bayrak[x.icerik] || 0) + 1;
    if(x.mentor) mentorlar.push({ isim: adElYazisi(o.isim), icerik: x.icerik }); }); }); });
  let sinif = { ad: sinifAd, yil: egitimYili || "", bolgeler: bolgeler,
    soru: ogr.reduce(function(t, o){ return t + ((o.yilOzeti || {}).soru || 0); }, 0),
    dogru: ogr.reduce(function(t, o){ return t + ((o.yilOzeti || {}).dogru || 0); }, 0),
    kesfedilen: bolgeler.reduce(function(t, b){ return t + b.icerikler.filter(function(x){ return x.n > 0; }).length; }, 0),
    mentorlar: mentorlar, enCokBayrak: Object.keys(bayrak).sort(function(a, b){ return bayrak[b] - bayrak[a]; }).slice(0, 4).map(function(k){ return { icerik: k, sayi: bayrak[k] }; }),
    not: not };
  ogr.forEach(function(o){
    let od = [];
    odulKayitlari(o).forEach(function(r){
      if(String(r.tur).indexOf("Onur Belgesi") === 0){ let p = String(r.neden || "").split(" · "); (p[1] || "").split(", ").filter(Boolean).forEach(function(a){ od.push("📜 " + a); }); }
      else if(String(r.tur).indexOf("Başarı Belgesi") === 0) od.push("🏆 Başarı Belgesi");
    });
    o.ykOdul = od;
  });
  let html = ykKapakHtml(sinif) + ykSinifHtml(sinif) + ogr.map(function(o, i){ return ykOgrenciHtml(o, i + 3, sinif); }).join("");
  odulYazdir(html, "Yillik-" + sinifAd + "-" + (egitimYili || ""));
}

// ================= 🗺️ SINIF HARİTASI VE MENTORLAR (v3.30, Code.gs v2.19) =================
// Her öğrencide "harita" (seçilen sınava kadarki havuzlanmış başarıyla). Mentor adayı: bir içerikte 👑 Usta olanlar.
// Mentor yapma/kaldırma kararı öğretmenin; veli sayfasında başka öğrencinin adı görünmez.
const SH_SEV = [["usta","👑 Usta","#FACC15"],["saglam","🌳 Sağlam","#22C55E"],["filiz","🌱 Filiz","#86EFAC"],["kesif","🏕️ Keşifte","#FCD34D"]];
function mentorSatiriHtml(o){
  let h = o.harita; if(!h) return "";
  let m = [];
  h.bolgeler.forEach(function(b){ b.icerikler.forEach(function(x){ if(x.mentor) m.push(x.icerik); }); });
  return m.length ? `<div class="mnOgrSatir">🤝 Mentor: ${htmlKacis(m.join(", "))}</div>` : "";
}
function sinifHaritasiKur(liste){
  let ogr = liste.filter(function(o){ return o.harita && o.harita.toplam; });
  let eski = document.getElementById("sinifHaritaKart"); if(eski) eski.remove();
  if(!ogr.length){ yuvayiBosalt("yuvaHarita"); return; }
  // İçerik sırası: bölgelerle birlikte, bütün öğrencilerin haritalarının birleşimi
  let bolgeler = [], bolgeMap = {};
  ogr.forEach(function(o){ o.harita.bolgeler.forEach(function(b){
    if(!bolgeMap[b.ad]){ bolgeMap[b.ad] = { ad: b.ad, icerikler: [] }; bolgeler.push(bolgeMap[b.ad]); }
    b.icerikler.forEach(function(x){ if(bolgeMap[b.ad].icerikler.indexOf(x.icerik) === -1) bolgeMap[b.ad].icerikler.push(x.icerik); });
  }); });
  let bul = function(o, ic){ let r = null; o.harita.bolgeler.forEach(function(b){ b.icerikler.forEach(function(x){ if(x.icerik === ic) r = x; }); }); return r; };
  let satirlar = "";
  bolgeler.forEach(function(b){
    satirlar += `<tr class="shBolge"><td colspan="3">${htmlKacis(b.ad)}</td></tr>`;
    b.icerikler.forEach(function(ic){
      let g = { usta:[], saglam:[], filiz:[], kesif:[], sis:[] }, mentorlar = [];
      ogr.forEach(function(o){ let x = bul(o, ic); let sv = x ? x.seviye : "sis"; g[sv].push(o); if(x && x.mentor) mentorlar.push(o); });
      let acik = ogr.length - g.sis.length;
      if(!acik){ satirlar += `<tr><td><b>${htmlKacis(ic)}</b></td><td colspan="2" style="color:var(--gray)">🌫️ Henüz sınavı yapılmadı</td></tr>`; return; }
      let dagilim = SH_SEV.map(function(sv){ return `<i style="width:${g[sv[0]].length / acik * 100}%;background:${sv[2]}" title="${sv[1]}: ${g[sv[0]].length}"></i>`; }).join("");
      let sayilar = SH_SEV.map(function(sv){ return sv[1].split(" ")[0] + " " + g[sv[0]].length; }).join(" · ");
      let adaylar = g.usta.slice();
      mentorlar.forEach(function(o){ if(adaylar.indexOf(o) === -1) adaylar.push(o); });
      let adayHtml = adaylar.length ? adaylar.map(function(o){
          let aktif = mentorlar.indexOf(o) !== -1, i = liste.indexOf(o);
          return `<span class="shAday">${aktif ? "🤝" : "👑"} ${htmlKacis(o.isim)}<button type="button" class="shMentorBtn${aktif ? " aktif" : ""}" data-ogr="${i}" data-icerik="${htmlKacis(ic)}" data-durum="${aktif ? "pasif" : "aktif"}">${aktif ? "Mentor ✓ (Kaldır)" : "Mentor Yap"}</button></span>`;
        }).join("") : `<span style="color:var(--gray)">Henüz usta yok</span>`;
      let kesifte = g.kesif.length ? `<div class="shIsim">🏕️ Keşifte: ${htmlKacis(g.kesif.map(function(o){ return o.isim; }).join(", "))}</div>` : "";
      satirlar += `<tr><td><b>${htmlKacis(ic)}</b></td><td><div class="shSayi">${sayilar}</div><div class="shDagilim">${dagilim}</div></td><td>${adayHtml}${kesifte}</td></tr>`;
    });
  });
  let kart = document.createElement("div");
  kart.className = "anKart"; kart.id = "sinifHaritaKart";
  kart.innerHTML = `<div class="anBaslik"><h3>🗺️ Sınıf Haritası ve Mentorlar</h3><small>${ogr.length} öğrenci · bu sınava kadarki bütün sınavlar · tüm şubeler</small></div>
    <div style="overflow-x:auto"><table class="shTablo"><thead><tr><th>İçerik</th><th>Sınıfın Durumu</th><th>🤝 Mentor Adayları (👑 Usta) · 🏕️ Keşifte Olanlar</th></tr></thead><tbody>${satirlar}</tbody></table></div>
    <div class="anNot">Mentor adayı: o içerikte %90 ve üstü başarısı olan (en az ${ogr[0].harita.ustaMinSoru || 4} soruyla) öğrenciler. "Mentor Yap" dediğin öğrenci kendi haritasında o içerikte 🤝 görür ve 🤝 Mentor rozetini alır.
      Keşifte olanların adları yalnızca sende görünür; veli sayfasında başka hiçbir öğrencinin adı geçmez, eşleştirmeyi sınıfta sen yaparsın.</div>
    <div class="raporIpucu" id="shDurum" role="status" aria-live="polite"></div>`;
  let mentorSay = 0;
  ogr.forEach(function(o){ o.harita.bolgeler.forEach(function(b){ b.icerikler.forEach(function(x){ if(x.mentor) mentorSay++; }); }); });
  bolumeYerlestir("yuvaHarita", "sinifHaritasi", "🗺️", "Sınıf Haritası ve Mentorlar", `${ogr.length} öğrenci · ${mentorSay} mentorluk`, kart, false);
  kart.querySelectorAll(".shMentorBtn").forEach(function(b){ b.onclick = function(){ mentorDegistir(liste, b); }; });
}
async function mentorDegistir(liste, dugme){
  let o = liste[Number(dugme.getAttribute("data-ogr"))], ic = dugme.getAttribute("data-icerik"), durum = dugme.getAttribute("data-durum");
  let anahtar = ogretmenAnahtari(), bilgi = document.getElementById("shDurum");
  dugme.disabled = true; dugme.textContent = "⏳";
  try{
    let veri = await jsonOku(await apiIstek({ mentorKaydet: "1", anahtar: anahtar, isim: o.isim, girisKodu: o.girisKodu || "", icerik: ic, durum: durum }, 20000));
    if(veri && veri.ok){
      o.harita.bolgeler.forEach(function(b){ b.icerikler.forEach(function(x){ if(x.icerik === ic) x.mentor = durum === "aktif"; }); });
      sinifHaritasiKur(liste);
      let yeni = document.getElementById("shDurum");
      if(yeni) yeni.textContent = durum === "aktif" ? `🤝 ${o.isim}, ${ic} içeriğinde mentor yapıldı. Veli sayfasında bir sonraki girişte görünür.` : `${o.isim} artık ${ic} içeriğinde mentor değil.`;
      return;
    }
    if(bilgi) bilgi.textContent = "⚠️ Kaydedilemedi: " + ((veri && (veri.mesajTr || veri.hata)) || "bilinmeyen hata");
  }catch(e){ if(bilgi) bilgi.textContent = "⚠️ Kaydedilemedi (bağlantı)."; }
  dugme.disabled = false; dugme.textContent = durum === "aktif" ? "Mentor Yap" : "Mentor ✓ (Kaldır)";
}

// ================= 🏔️ HEDEFİM (v3.29, Code.gs v2.18) =================
// Her öğrencide "hedefim": {tur: lgs|seviye, simdi:{puan, seviye}, hedef, ulasti, soruSayisi, esikler}. Seçilen sınava
// kadarki son 3 sınavın ortalamasıyla. Öğrenci hedefini yalnızca yükseltebilir; zorlanan öğrencinin hedefini buradan
// sıfırlarsın, öğrenci bir sonraki girişinde kendi seviyesine göre yeniden seçer.
function hdNetOgr(h, puan){ return h.tur === "lgs" ? puan / 5 : puan * (h.soruSayisi || 20) / 100; }
function hdSayiOgr(x){ return String(Math.round(Number(x) * 100) / 100).replace(".", ","); }
function hedefSatiriHtml(o, idx){
  let h = o.hedefim;
  if(!h || !h.simdi) return "";
  let simdi = hdSayiOgr(hdNetOgr(h, h.simdi.puan)) + " net (" + h.simdi.seviye + ")";
  if(!h.hedef) return `<div class="hdOgrSatir yok">🏔️ Yıl hedefi henüz seçilmedi · şu an ${htmlKacis(simdi)}</div>`;
  let oran = h.hedef.hedefPuan > 0 ? Math.max(0, Math.min(100, h.simdi.puan / h.hedef.hedefPuan * 100)) : 100;
  return `<div class="hdOgrSatir${h.ulasti ? " zirve" : ""}" id="hdSatir_${idx}">🏔️ ${htmlKacis(h.hedef.metin)}
    <span>· şu an ${htmlKacis(simdi)}${h.ulasti ? " · ✅ ulaştı" : ""}</span>
    ${h.ulasti ? "" : `<span class="hdCubuk" title="Hedefe yakınlık"><i style="width:${oran}%"></i></span>`}
    <button type="button" class="hdSifirlaBtn" id="hdSifirla_${idx}" title="Hedefi sıfırla: öğrenci bir sonraki girişinde yeniden seçer">↺ Sıfırla</button></div>`;
}
async function hedefiSifirla(o, idx, dugme){
  if(!confirm(o.isim + " için yıl hedefi (" + o.hedefim.hedef.metin + ") sıfırlansın mı?\nÖğrenci bir sonraki girişinde kendi seviyesine göre yeniden seçecek.")) return;
  let anahtar = ogretmenAnahtari();
  dugme.disabled = true; dugme.textContent = "⏳";
  try{
    let res = await apiIstek({ hedefSifirla: "1", anahtar: anahtar, isim: o.isim, girisKodu: o.girisKodu || "" }, 20000);
    let veri = await jsonOku(res);
    if(veri && veri.ok){
      o.hedefim.hedef = null; o.hedefim.ulasti = false;
      let satir = document.getElementById("hdSatir_" + idx);
      if(satir) satir.outerHTML = hedefSatiriHtml(o, idx);
      satirBildirimi(idx, "🏔️ Hedef sıfırlandı; öğrenci yeniden seçecek.", "ok", BILDIRIM_SURESI_MS);
      return;
    }
    satirBildirimi(idx, "⚠️ Hedef sıfırlanamadı: " + ((veri && (veri.mesajTr || veri.hata)) || "bilinmeyen hata"), "hata", BILDIRIM_SURESI_MS);
  }catch(e){
    satirBildirimi(idx, "⚠️ Hedef sıfırlanamadı (bağlantı).", "hata", BILDIRIM_SURESI_MS);
  }
  dugme.disabled = false; dugme.textContent = "↺ Sıfırla";
}
function hedefOzeti(liste){
  let olan = liste.filter(function(o){ return o.hedefim && o.hedefim.simdi; });
  if(!olan.length) return;
  let secen = olan.filter(function(o){ return o.hedefim.hedef; });
  let ulasan = secen.filter(function(o){ return o.hedefim.ulasti; }).length;
  let lgs = olan[0].hedefim.tur === "lgs";
  let kutu = document.createElement("div");
  kutu.className = "moOzet"; kutu.style.borderColor = "#99F6E4";
  kutu.innerHTML = `<h3>${lgs ? "🎓 LGS Hedefleri" : "🏔️ Yıl Sonu Hedefleri"}</h3>
    <div class="moOzetSayilar">
      <div style="background:#F0FDFA"><b>${secen.length}/${olan.length}</b><small>hedef seçti</small></div>
      <div style="background:#F0FDFA"><b>${ulasan}</b><small>✅ ulaştı</small></div>
      <div style="background:#F0FDFA"><b>${secen.length - ulasan}</b><small>🚩 yolda</small></div>
      <div style="background:#F0FDFA"><b>${olan.length - secen.length}</b><small>seçmedi</small></div>
    </div>
    <div class="moOzetSatir">Durum, bu sınava kadarki son 3 sınavın ortalamasıyla hesaplanır. Öğrenci hedefini yalnızca yükseltebilir; zorlanan öğrencinin hedefini satırındaki "↺ Sıfırla" ile sıfırlayabilirsin.</div>`;
  bolumeYerlestir("yuvaHedef", "hedefler", lgs ? "🎓" : "🏔️", lgs ? "LGS Hedefleri" : "Yıl Sonu Hedefleri",
    `${secen.length}/${olan.length} hedef seçti · ${ulasan} ulaştı`, kutu, false);
}

// Öğrenci listesindeki KISA satır: ad, net/sıra özeti, Önizle + aynı üç numaralı işlem düğmesi.
// (Büyük kart burada çizilmez, bkz. karneKartiHtml.)
function olustur(o, idx){
  let listeEl = document.getElementById(o.bireysel ? "bireyselKarneler" : "sinifKarneler") || document.getElementById("karnePaneli");
  let blok = document.createElement("div");
  blok.className = "ogrenciSatir";
  blok.setAttribute("data-takip", takipDurumu(o));

  let ozet = o.bireysel
    ? "Net " + kSayi(o.net) + " · " + htmlKacis(sinifEtiketi(o))
    : "Net " + kSayi(o.net) + " · Sıra " + (o.sira ? (o.sira + "/" + (o.katilim || "-")) : "-");
  let gonderildi = ilkMesajGonderildiMi(o);

  // Telefon eksik mi, yoksa (Ogrenciler sayfasına "1234" gibi) açıkça hatalı/çok kısa mı yazılmış —
  // ikisinde de WhatsApp düğmeleri kilitlenir, ama farklı bir uyarı metniyle (eskiden yalnızca "eksik"
  // durumu uyarıyordu; hatalı-ama-dolu bir numara sessizce yanlış bir WhatsApp bağlantısı açıyordu).
  let telefonUyariHtml = !o.veliTelefon
    ? `<div class="telefonYok">⚠️ Bu öğrencinin veli telefonu Ogrenciler sayfasında eksik.</div>`
    : (telefonCokKisaMi(o.veliTelefon)
        ? `<div class="telefonYok">⚠️ Bu öğrencinin veli telefonu hatalı görünüyor ("${htmlKacis(o.veliTelefon)}") — Ogrenciler sayfasında kontrol et.</div>`
        : "");

  blok.innerHTML = `
    <div class="ogrenciSatirUst">
      <div class="ogrenciAd">${htmlKacis(o.isim)}<span class="gonderildiRozet" id="gonderildiRozet_${idx}" style="${gonderildi ? "" : "display:none;"}">✓ Gönderildi</span></div>
      <div class="ogrenciOzet">${ozet}</div>
    </div>
    ${takipSatiriHtml(o, idx)}
    ${moSatiriHtml(o)}
    ${hedefSatiriHtml(o, idx)}
    ${mentorSatiriHtml(o)}
    <div class="aksiyonlar" style="margin-top:10px;">
      <button class="btnOnizle" id="onizle_${idx}">👁️ Önizle</button>
      <button class="btnOnizle btnHdTek" id="hd_${idx}" title="Bu öğrencinin hata defterini yazdır / PDF">📘 Hata Defteri</button>
    </div>
    <div class="onizleAlan" id="onizleAlan_${idx}" style="display:none;"></div>
    <div class="aksiyonlar">
      <button class="btnWa${gonderildi ? " btnWaGonderildi" : ""}" id="wa_${idx}">${gonderildi ? "✓ İlk Mesaj Gönderildi (Tekrar Gönder)" : "1. İlk Mesajı Gönder"}</button>
      <button class="btnPng" id="kopya_${idx}" data-etiket="karne">${dugmeEtiketi("karne")}</button>
    </div>
    <div class="aksiyonlar">
      <button class="btnWa2" id="waDetay_${idx}" data-etiket="son">${dugmeEtiketi("son")}</button>
    </div>
    <div class="aksiyonlar">
      <button class="btnHdGonder" id="hdGonder_${idx}" title="Hata defterini PDF olarak indirir ve velinin WhatsApp sohbetini açar">4. Hata Defterini Gönder</button>
    </div>
    ${telefonUyariHtml}
    ${!o.girisKodu ? `<div class="telefonYok">⚠️ Bu öğrencinin Giriş Kodu yok. Sheets menüsünden "🔑 Giriş Kodlarını Üret" komutunu çalıştır.</div>` : ""}
    <div class="satirDurum" id="durum_${idx}" role="status" aria-live="polite"></div>
  `;

  listeEl.appendChild(blok);

  // "Önizle": kartın TAM OLARAK export edilecek hâliyle aynı HTML'ini (karneKartiHtml) sayfanın içinde,
  // ekran dışına çıkmadan gösterir/gizler — kopyalamadan/göndermeden önce görsel bir kontrol imkânı.
  // İçerik yalnızca ilk açılışta bir kez kuruluyor (o, bu satırın ömrü boyunca değişmiyor), sonraki
  // tıklamalarda yalnızca gizle/göster.
  document.getElementById("onizle_"+idx).onclick = function(){
    let alan = document.getElementById("onizleAlan_"+idx);
    if(alan.style.display === "none"){
      if(!alan.dataset.dolduruldu){ alan.innerHTML = karneKartiHtml(o, "onizleKart_"+idx); alan.dataset.dolduruldu = "1"; }
      alan.style.display = "block";
      this.textContent = "✖️ Önizlemeyi Kapat";
    }else{
      alan.style.display = "none";
      this.textContent = "👁️ Önizle";
    }
  };

  document.getElementById("kopya_"+idx).onclick = function(){ karneyiKopyala(o, idx); };
  let hdSifirla = document.getElementById("hdSifirla_" + idx);
  if(hdSifirla) hdSifirla.onclick = function(){ hedefiSifirla(o, idx, hdSifirla); };
  document.getElementById("hdGonder_"+idx).onclick = function(){ hataDefteriniVeliyeGonder(o, idx); };
  document.getElementById("hd_"+idx).onclick = function(){
    hataDefterleriniYazdir([o], function(m, tur){ satirBildirimi(idx, (tur === "hata" ? "⚠️ " : "📘 ") + m, tur === "hata" ? "hata" : "ok", BILDIRIM_SURESI_MS); });
  };

  let waBtn = document.getElementById("wa_"+idx);
  let waDetayBtn = document.getElementById("waDetay_"+idx);
  if(!o.veliTelefon || telefonCokKisaMi(o.veliTelefon)){
    waBtn.disabled = true;
    waDetayBtn.disabled = true;
  } else {
    waBtn.onclick = function(){
      let telefon = normalizeTelefon(o.veliTelefon);
      let BAR_EMOJI = String.fromCodePoint(0x1F4CA);   // 📊
      let MEMO_EMOJI = String.fromCodePoint(0x1F4DA);  // 📚
      // Veli Hitap doluysa ("Ali Bey", "Ayşe Hanım" gibi) kişiselleştirilmiş selamla başlar;
      // Ogrenciler sayfasında bu sütun yoksa ya da o satırda boşsa eski genel "Merhaba," aynen kalır.
      let selam = o.veliHitap ? `Merhaba ${o.veliHitap},` : `Merhaba,`;
      let mesaj = `${selam}\n\nÖğrencimiz ${o.isim} için hazırladığım *${o.sinav} Analiz Karnesi*'ni birazdan gönderiyorum.\n\n${BAR_EMOJI} Karnede; net, puan, sıralama, genel başarı ve içerik analizleri yer almaktadır.\n\n${MEMO_EMOJI} Karneyi incelemenizi rica eder, hayırlı günler dilerim.\n\n— Fatih Hoca ${IMZA_EMOJI}`;
      whatsappAc(telefon, mesaj);
      ilkMesajGonderildiIsaretle(o);
      gonderildiUIGuncelle(idx, waBtn);
    };
    waDetayBtn.onclick = async function(){
      satirBildirimiTemizle(idx);
      let LINK_EMOJI = String.fromCodePoint(0x1F517);  // 🔗
      let KISI_EMOJI = String.fromCodePoint(0x1F464);  // 👤
      let ANAHTAR_EMOJI = String.fromCodePoint(0x1F511); // 🔑
      let KILIT_EMOJI = String.fromCodePoint(0x1F512);   // 🔒
      // Düzen: önce giriş bilgileri, bağlantı EN ALTTA. WhatsApp önizleme kartını adresin yerinden bağımsız
      // olarak mesajın en üstüne koyar; adres altta olunca velinin sohbet listesinde ve bildiriminde ilk
      // satır olarak "Giriş Bilgileri" görünür. Tanıtım metnini artık kart taşıyor (index.html'deki og etiketleri).
      // trim(): WhatsApp'ta kalın yazı (*...*) yıldızın yanında boşluk varsa çalışmaz ve yıldızlar görünür kalır;
      // hücre sonunda fark edilmeyen bir boşluk bu yüzden mesajı bozmasın.
      let adSoyad = String(o.isim || "").trim();
      let girisKodu = String(o.girisKodu || "").trim();
      let mesaj2 = `*Giriş Bilgileri*\n${KISI_EMOJI} Ad Soyad: *${adSoyad}*\n${ANAHTAR_EMOJI} Giriş Kodu: *${girisKodu}*\n\n${KILIT_EMOJI} _Giriş kodu öğrencimize özeldir. Lütfen kimseyle paylaşmayınız._\n\n${LINK_EMOJI} ${SITE_ADRESI}`;
      if(whatsappHedefi() === "masaustu"){
        whatsappAc(normalizeTelefon(o.veliTelefon), mesaj2);
        satirBildirimi(idx, "✅ Son mesaj WhatsApp'ta yazı kutusunda hazır — Enter'a bas.", "ok", BILDIRIM_SURESI_MS);
        return;
      }
      try{
        await navigator.clipboard.writeText(mesaj2);
        satirBildirimi(idx, "✅ Mesaj panoya kopyalandı — WhatsApp sohbetine yapıştır (Ctrl+V), sonra Gönder'e bas.", "ok", BILDIRIM_SURESI_MS);
      }catch(err){
        let telefon = normalizeTelefon(o.veliTelefon);
        whatsappAc(telefon, mesaj2);
        satirBildirimi(idx, "⚠️ Pano kullanılamadı; mesaj WhatsApp'ta hazır metin olarak açıldı, Gönder'e basman yeterli.", "uyari");
      }
    };
  }
  // Giriş Kodu yoksa "Son Mesaj" kodsuz gitmesin diye kapalı kalır (ilk mesaj/karne etkilenmez).
  if(!o.girisKodu){ waDetayBtn.disabled = true; }

}

// "2. Karneyi Kopyala": karne kartı ekran DIŞINDA, sabit genişlikte anlık oluşturulur, görüntüsü alınıp panoya kopyalanır,
// sonra kart silinir. Böylece sayfa şişmez ve görsel pencere genişliğinden bağımsız hep aynı boyutta çıkar.
async function karneyiKopyala(o, idx){
  let btn = document.getElementById("kopya_" + idx);
  let btnMetni = btn.textContent;
  satirBildirimiTemizle(idx);
  btn.disabled = true;
  btn.textContent = "⏳ Hazırlanıyor…";

  let gecici = document.createElement("div");
  gecici.className = "karneGeciciAlan";
  let cardId = "karne_gecici_" + idx; // her satır için ayrı kimlik: aynı anda iki satıra basılırsa karneler karışmasın
  document.body.appendChild(gecici);
  try{
    karneCerceveKur(gecici, o, cardId); // sabit oranlı çerçeve (içeriğe göre en küçük uygun genişlik)
    let sonuc = await pngIndir(cardId, o.isim);
    // Masaüstü modunda: karne panoya girdikten SONRA o velinin sohbeti uygulamada öne getirilir. Sıra önemli:
    // uygulama öne gelince tarayıcı odağı kaybeder ve odaksız sayfa panoya yazamaz.
    let sohbetAcilsin = sonuc === "pano" && whatsappHedefi() === "masaustu" && o.veliTelefon && !telefonCokKisaMi(o.veliTelefon);
    if(sohbetAcilsin){
      whatsappAc(normalizeTelefon(o.veliTelefon), "");
      satirBildirimi(idx, "✅ Karne panoda ve " + String(o.isim || "").trim() + " velisinin sohbeti açıldı — Ctrl+V, sonra Enter. (Sohbet öne gelmediyse WhatsApp'a kendin geç.)", "ok", BILDIRIM_SURESI_MS);
    }else if(sonuc === "pano"){
      satirBildirimi(idx, "✅ Karne panoya kopyalandı — WhatsApp sohbetine yapıştır (Ctrl+V), sonra Gönder'e bas.", "ok", BILDIRIM_SURESI_MS);
    }else{
      satirBildirimi(idx, "⬇️ Bu tarayıcıda panoya kopyalama desteklenmiyor; görsel indirildi (İndirilenler klasörü). WhatsApp sohbetine sürükleyip gönder.", "uyari");
    }
  }catch(err){
    console.error(err);
    let hataMetni = (typeof html2canvas === "undefined") ? "Görsel oluşturma bileşeni yüklenemedi" : (err && err.message ? err.message : String(err));
    satirBildirimi(idx, "⚠️ Karne kopyalanamadı (" + hataMetni + "). Sayfayı yenileyip tekrar dene.", "hata");
  }finally{
    gecici.remove();
    btn.disabled = false;
    btn.textContent = btnMetni;
  }
}

function canvasBlob(canvas){
  return new Promise(function(coz, reddet){
    canvas.toBlob(function(blob){ blob ? coz(blob) : reddet(new Error("görsel üretilemedi")); }, "image/png");
  });
}

async function pngIndir(cardId, isim){
  let el = document.getElementById(cardId);
  // v3.43: imza altındaki ad/unvan (Playfair, gömülü) görüntü alınmadan önce yüklensin; yoksa ilk karnede yedek yazı tipi çıkar
  if(document.fonts && document.fonts.load){
    try{ await Promise.all(["900 14px OdPlayfair", "400 12px OdPlayfair"].map(function(f){ return document.fonts.load(f, "Fatih KARYAĞDI Matematik Öğretmeni"); })); }catch(e){}
  }
  let canvas = await html2canvas(el, {scale:2, backgroundColor:"#ffffff", useCORS:true});
  let blob = await canvasBlob(canvas);

  // Dönüş: "pano" (panoya kopyalandı) ya da "indirildi" (pano desteklenmiyor → dosya olarak indirildi). Bildirimi çağıran satır gösterir.
  try{
    await navigator.clipboard.write([ new ClipboardItem({ "image/png": blob }) ]);
    return "pano";
  }catch(err){
    // Panoya kopyalama desteklenmiyorsa (bazı tarayıcı/izin durumları), indirmeye geri düş
    let link = document.createElement("a");
    link.download = isim.trim().replace(/\s+/g,"_") + "_karne.png";
    link.href = canvas.toDataURL("image/png");
    link.click();
    return "indirildi";
  }
}

// ================= TG DENEMELERİ HATA DEFTERİ (v3.18) =================
// Türkiye geneli (TG) denemelerinden, öğrenciye özel hata defteri. Her deneme sonucu (öğrenci + deneme + yanlış/boş
// numaraları) Ek_Kayitlar'a kaydedilir; normal föydeki gibi her EK_BLOK kayıt bir föy olur (Föy 1 = 1–3. kayıt...).
// Sorular tg-defter.html'de kesilip kütüphaneye konur. Föy ANA föy motoruyla basılır (aynı dizgi, yazdırma, WhatsApp
// PDF'i). v3.48: istekler POST ile gider (apiIstek); bilgisayardan açılan sayfada POST engellenirse GET'e düşer.
const EK_DEFTER_ADRESI = "https://fatihhocaultramath.github.io/sonuc/tg-defter.html";
const EK_BLOK = 3;
let ekVeri = { ogrenciler: [], denemeler: [], kayitlar: [], yuklendi: false }, ekDuzenlenen = null;

async function ekApi(veri){
  let res;
  try{ res = await apiIstek(Object.assign({ anahtar: ogretmenAnahtari() }, veri), 30000); }
  catch(e){ throw new Error(e && e.isTimeout ? "Sunucu yanıt vermedi, birazdan tekrar dene." : "Sunucuya ulaşılamadı. İnternet bağlantını kontrol et."); }
  let j = await jsonOku(res);
  if(j && j.yetkisiz) throw new Error("Öğretmen anahtarı hatalı.");
  if(!j || typeof j.ok === "undefined") throw new Error("Sunucu bu isteği tanımadı. Code.gs'in yeni sürümü dağıtılmamış olabilir (Dağıt → Dağıtımları yönet → Yeni sürüm).");
  if(!j.ok && !j.onayGerekli) throw new Error(j.mesajTr || "İşlem yapılamadı.");
  return j;
}
function ekNumaralar(metin){
  let out = [];
  String(metin || "").split(/[^0-9]+/).forEach(function(p){ let n = parseInt(p, 10); if(n >= 1 && n <= 200 && out.indexOf(n) === -1) out.push(n); });
  return out.sort(function(a, b){ return a - b; });
}
// "10C, 12 b, 15" → { nolar, cevap:{10:"C",12:"B"}, metin:"10C, 12B, 15" } — öğrencinin şıkkı isteğe bağlı (Code.gs ile aynı kural)
function ekYanlisAyristir(m){
  let nolar = [], cevap = {};
  String(m || "").toUpperCase().replace(/(\d{1,3})\s*[-:]?\s*([A-E])?/g, function(_, n, h){ n = Number(n);
    if(n >= 1 && n <= 200 && nolar.indexOf(n) === -1){ nolar.push(n); if(h) cevap[n] = h; } return _; });
  nolar.sort(function(a, b){ return a - b; });
  return { nolar: nolar, cevap: cevap, metin: nolar.map(function(n){ return n + (cevap[n] || ""); }).join(", ") };
}
function ekYanlisMetni(k){ return k.yanlis.map(function(n){ return n + ((k.ogrCevap && k.ogrCevap[n]) || ""); }).join(", "); }
function ekOgrAnahtar(o){ return [String(o.isim).trim(), String(o.sinif || ""), String(o.sube || "")].join("|"); }
function ekSeciliOgr(){ let v = document.getElementById("ekOgr"); return v && v.value !== "" ? ekVeri.ogrenciler[Number(v.value)] : null; }
function ekDeneme(id){ return ekVeri.denemeler.find(function(d){ return d.id === id; }) || null; }
function ekOgrKayitlari(o){
  let k = ekOgrAnahtar(o);
  return ekVeri.kayitlar.filter(function(x){ return ekOgrAnahtar(x) === k; }).sort(function(a, b){ return String(a.zaman).localeCompare(String(b.zaman)); });
}
function ekDurum(m, tur){ let d = document.getElementById("ekDurum"); if(d){ d.textContent = m || ""; d.className = "ekDurum" + (tur === "hata" ? " hata" : ""); } }

function ekPanelCiz(){
  let p = document.getElementById("ekPanel"), gruplar = {};
  ekVeri.ogrenciler.forEach(function(o, i){ let g = hdSinifMetni(o) || "Diğer"; (gruplar[g] = gruplar[g] || []).push(i); });
  let ogrSec = Object.keys(gruplar).sort(function(a, b){ return a.localeCompare(b, "tr", { numeric: true }); }).map(function(g){
    return `<optgroup label="${htmlKacis(g)}">${gruplar[g].map(function(i){ return `<option value="${i}">${htmlKacis(ekVeri.ogrenciler[i].isim)}</option>`; }).join("")}</optgroup>`;
  }).join("");
  p.innerHTML = `<h3>📘 TG Denemeleri Hata Defteri</h3>
    <div class="ekDurum">Öğrencinin girdiği TG denemelerindeki yanlış ve boş soruları kaydet. Her ${EK_BLOK} deneme bir föy olur.</div>
    <div class="ekIzgara"><div><label for="ekOgr">Öğrenci</label><select id="ekOgr"><option value="">— Öğrenci Seç —</option>${ogrSec}</select></div>
      <div style="display:flex;align-items:flex-end;gap:8px;flex-wrap:wrap"><a class="ekKucukBtn" style="text-decoration:none;padding:10px 12px" href="${EK_DEFTER_ADRESI}" target="_blank" rel="noopener">✂️ Soru Kütüphanesi</a>
      <button type="button" class="ekKucukBtn" id="ekYenile" style="padding:10px 12px">🔄 Yenile</button></div></div>
    <div id="ekOgrAlan"></div>
    <div class="ekDurum" id="ekDurum" role="status" aria-live="polite"></div>`;
  document.getElementById("ekOgr").onchange = function(){ ekDuzenlenen = null; ekOgrCiz(); };
  document.getElementById("ekYenile").onclick = function(){ ekYukle(true); };
}

function ekOgrCiz(){
  let alan = document.getElementById("ekOgrAlan"), o = ekSeciliOgr();
  if(!o){ alan.innerHTML = ""; return; }
  let denSec = ekVeri.denemeler.map(function(d){ return `<option value="${htmlKacis(d.id)}">${htmlKacis(d.ad)} (${htmlKacis(d.sinif)}. sınıf)</option>`; }).join("");
  let kayitlar = ekOgrKayitlari(o), d0 = ekDuzenlenen;
  let html = `<div class="ekBolum"><h4>${d0 ? "Kaydı düzelt" : "Deneme sonucu ekle"}</h4>
    <div class="ekIzgara" style="margin-top:4px">
      <div><label for="ekDen">Deneme</label><select id="ekDen"><option value="">— Deneme Seç —</option>${denSec}</select></div><div></div>
      <div><label for="ekYanlis">Yanlış Sorular</label><input type="text" id="ekYanlis" placeholder="ör. 4C, 9, 13A"><div style="font-size:12px;color:#64748B;margin-top:3px">Öğrencinin işaretlediği şıkkı biliyorsan numaranın yanına yaz (isteğe bağlı).</div></div>
      <div><label for="ekBos">Boş Sorular</label><input type="text" id="ekBos" inputmode="numeric" placeholder="ör. 17, 20"></div></div>
    <div class="ekDugmeler"><button type="button" class="ekAna" id="ekKaydet">${d0 ? "💾 Düzeltmeyi Kaydet" : "💾 Kaydet"}</button>${d0 ? '<button type="button" id="ekVazgec">Vazgeç</button>' : ""}</div></div>`;
  if(!kayitlar.length) html += `<div class="ekBolum"><div class="ekDurum">Bu öğrencinin henüz TG denemesi kaydı yok.</div></div>`;
  for(let f = 0; f * EK_BLOK < kayitlar.length; f++){
    let blok = kayitlar.slice(f * EK_BLOK, (f + 1) * EK_BLOK), tamam = blok.length >= EK_BLOK, eksikVar = false;
    let satirlar = blok.map(function(k){
      let d = ekDeneme(k.denemeID), lib = {}; (d ? d.sorular : []).forEach(function(q){ lib[q.no] = true; });
      let hepsi = k.yanlis.concat(k.bos), eksik = hepsi.filter(function(n){ return !lib[n]; });
      if(eksik.length || !d) eksikVar = true;
      let cipler = hepsi.sort(function(a, b){ return a - b; }).map(function(n){ return `<span class="ekNo ${lib[n] ? "var" : "yok"}" title="${k.bos.indexOf(n) !== -1 ? "boş" : "yanlış"}">${n}</span>`; }).join("");
      return `<div class="ekKayit"><b>${d ? htmlKacis(d.ad) : "⚠️ silinmiş deneme"}</b>
        <span>Yanlış: ${ekYanlisMetni(k) || "—"} · Boş: ${k.bos.join(", ") || "—"}</span><span>${cipler}</span>
        ${eksik.length && d ? `<a class="ekKucukBtn" style="text-decoration:none" target="_blank" rel="noopener" href="${EK_DEFTER_ADRESI}?deneme=${encodeURIComponent(d.id)}&eksik=${eksik.join(",")}">✂️ Eksik ${eksik.length} Soruyu Kes</a>` : ""}
        <button type="button" class="ekKucukBtn" data-duz="${htmlKacis(k.id)}">✏️ Düzelt</button><button type="button" class="ekKucukBtn sil" data-sil="${htmlKacis(k.id)}">Sil</button></div>`;
    }).join("");
    html += `<div class="ekBolum"><h4>TG Denemeleri · Föy ${f + 1} <span class="ekRozet ${tamam ? "hazir" : "bekliyor"}">${tamam ? "✅ hazır" : "⏳ " + blok.length + "/" + EK_BLOK + " deneme"}</span></h4>${satirlar}
      ${eksikVar ? `<div class="ekDurum" style="color:#854F0B">Turuncu sorular kütüphanede yok; föyü basmadan önce kes, sonra 🔄 Yenile.</div>` : ""}
      <div class="ekDugmeler"><button type="button" class="ekAna" data-yazdir="${f}"${eksikVar ? " disabled" : ""}>🖨️ Föyü Yazdır</button>
      <button type="button" class="ekAna" data-gonder="${f}"${eksikVar || !o.veliTelefon || telefonCokKisaMi(o.veliTelefon) ? " disabled" : ""}>📲 Veliye WhatsApp ile Gönder</button></div></div>`;
  }
  alan.innerHTML = html;
  if(d0){ document.getElementById("ekDen").value = d0.denemeID; document.getElementById("ekYanlis").value = ekYanlisMetni(d0); document.getElementById("ekBos").value = d0.bos.join(", "); }
  document.getElementById("ekKaydet").onclick = ekKayitKaydet;
  let vz = document.getElementById("ekVazgec"); if(vz) vz.onclick = function(){ ekDuzenlenen = null; ekOgrCiz(); };
  alan.querySelectorAll("[data-duz]").forEach(function(b){ b.onclick = function(){ ekDuzenlenen = ekVeri.kayitlar.find(function(k){ return k.id === b.dataset.duz; }); ekOgrCiz(); document.getElementById("ekYanlis").focus(); }; });
  alan.querySelectorAll("[data-sil]").forEach(function(b){ b.onclick = async function(){
    if(!window.confirm("Bu deneme kaydı silinsin mi? Föy numaraları sonraki kayıtlara göre yeniden oluşur.")) return;
    b.disabled = true;
    try{ let j = await ekApi({ ekIslem: "ekKayitSil", id: b.dataset.sil }); ekVeri.kayitlar = j.kayitlar; ekDuzenlenen = null; ekOgrCiz(); ekDurum("Kayıt silindi."); }
    catch(e){ ekDurum(hataMetni(e), "hata"); b.disabled = false; }
  }; });
  alan.querySelectorAll("[data-yazdir]").forEach(function(b){ b.onclick = function(){ ekFoy(Number(b.dataset.yazdir), "yazdir", b); }; });
  alan.querySelectorAll("[data-gonder]").forEach(function(b){ b.onclick = function(){ ekFoy(Number(b.dataset.gonder), "gonder", b); }; });
}

async function ekKayitKaydet(){
  let o = ekSeciliOgr(), did = document.getElementById("ekDen").value;
  let ya = ekYanlisAyristir(document.getElementById("ekYanlis").value), y = ya.nolar, bo = ekNumaralar(document.getElementById("ekBos").value);
  if(!did){ ekDurum("Denemeyi seç.", "hata"); return; }
  if(!y.length && !bo.length){ ekDurum("Yanlış ya da boş soru numarası yaz.", "hata"); return; }
  if(!ekDuzenlenen && ekOgrKayitlari(o).some(function(k){ return k.denemeID === did; })
     && !window.confirm("Bu öğrencinin bu denemeden zaten kaydı var. Yeni numaralarla güncellensin mi?")) return;
  let btn = document.getElementById("ekKaydet"); btn.disabled = true;
  try{
    let v = { ekIslem: "ekKayitKaydet", isim: o.isim, sinif: o.sinif, sube: o.sube, denemeID: did, yanlis: ya.metin, bos: bo.join(",") };
    if(ekDuzenlenen) v.id = ekDuzenlenen.id;
    let j = await ekApi(v); ekVeri.kayitlar = j.kayitlar; ekDuzenlenen = null; ekOgrCiz();
    ekDurum(j.guncellendi ? "Kayıt güncellendi." : "Kaydedildi.");
  }catch(e){ ekDurum(hataMetni(e), "hata"); btn.disabled = false; }
}

async function ekYukle(yenile){
  let p = document.getElementById("ekPanel");
  if(!ogretmenAnahtari()){ p.innerHTML = `<div class="ekDurum hata">Önce yukarıya öğretmen anahtarını yaz, sonra düğmeye yeniden bas.</div>`; ekVeri.yuklendi = false; return; }
  let secili = yenile && document.getElementById("ekOgr") ? document.getElementById("ekOgr").value : "";
  if(yenile) ekDurum("Yenileniyor…");   // v3.32: ilk açılışta "yükleniyor" yazısı panelde değil, düğmede görünür
  try{
    let r = await Promise.all([ekApi({ ekIslem: "ekOgrenciler" }), ekApi({ ekIslem: "ekListe" }), ekApi({ ekIslem: "ekKayitlar" })]);
    ekVeri = { ogrenciler: r[0].ogrenciler || [], denemeler: r[1].denemeler || [], kayitlar: r[2].kayitlar || [], yuklendi: true };
    ekPanelCiz();
    if(secili !== ""){ document.getElementById("ekOgr").value = secili; ekOgrCiz(); ekDurum("Yenilendi."); }
  }catch(e){ ekVeri.yuklendi = false; p.innerHTML = `<div class="ekDurum hata">⚠️ ${htmlKacis(hataMetni(e))}</div>`; }
}

async function ekFoy(f, tur, btn){
  let o = ekSeciliOgr(); if(!o) return;
  let blok = ekOgrKayitlari(o).slice(f * EK_BLOK, (f + 1) * EK_BLOK), eski = btn.textContent;
  hdEk = { foyNo: f + 1, sayi: blok.length };
  if(!hdBlokOnayi()){ hdEk = null; return; }
  btn.disabled = true; btn.textContent = "⏳ Görseller alınıyor…";
  try{
    let defter = [];
    for(const k of blok){
      let d = ekDeneme(k.denemeID), nolar = k.yanlis.concat(k.bos).sort(function(a, b){ return a - b; });
      let g = await ekApi({ ekIslem: "ekGorseller", denemeID: k.denemeID, nolar: nolar.join(",") });
      let eksik = nolar.filter(function(n){ return !g.gorseller[n]; });
      if(eksik.length) throw new Error(`${d.ad}: ${eksik.join(", ")} numaralı soruların görseli okunamadı. Kütüphaneden yeniden kes.`);
      let cevap = {}; d.sorular.forEach(function(q){ cevap[q.no] = q.dogru; });
      defter.push({ sinav: d.ad, sorular: nolar.map(function(n){ let bos = k.bos.indexOf(n) !== -1;
        return { no: n, konu: "", altKazanim: "", ogrenciSik: bos ? "" : ((k.ogrCevap && k.ogrCevap[n]) || "yanlış"), dogruSik: cevap[n] || "", durum: bos ? "Bos" : "Yanlis", soruGorseli: g.gorseller[n], cozumVideosu: "" }; }) });
    }
    let og = Object.assign({}, o, { hataDefteri: defter });
    btn.textContent = eski;
    if(tur === "gonder") await hataDefteriniVeliyeGonder(og, -1, { bildir: ekDurum, btn: btn });
    else await hataDefterleriniYazdir([og], ekDurum);
  }catch(e){ ekDurum(hataMetni(e), "hata"); }
  finally{ hdEk = null; btn.disabled = false; btn.textContent = eski; }
}

// v3.32: aç-kapa düğmesi. İlk açılışta veriler yüklenirken düğme "YÜKLENİYOR" gösterir ve kilitlenir
// (eskiden yükleme sürerken düğmeye tekrar basılınca panel kapanıyor, bir daha basılınca aynı veriler
// ikinci kez isteniyordu). Panel boş bir "yükleniyor" kutusuyla değil, veriler gelince dolu açılır;
// hata olursa hata mesajıyla açılır ve bir sonraki açılışta yeniden denenir.
const EK_BTN_AC = "TG Denemeleri Hata Defterini Aç", EK_BTN_KAPAT = "TG Denemeleri Hata Defterini Kapat";
function ekPanelGoster(acik){
  let p = document.getElementById("ekPanel"), b = document.getElementById("ekAcBtn");
  p.hidden = !acik;
  b.textContent = acik ? EK_BTN_KAPAT : EK_BTN_AC;
  b.setAttribute("aria-expanded", String(acik));
}
document.getElementById("ekAcBtn").onclick = async function(){
  let b = this;
  if(b.disabled) return;
  if(!document.getElementById("ekPanel").hidden){ ekPanelGoster(false); return; }
  if(!ekVeri.yuklendi){
    dugmeYukleniyor(b, true);
    try{ await ekYukle(false); }
    finally{ dugmeYukleniyor(b, false); }
  }
  ekPanelGoster(true);
};

// v3.32: Enter tuşu (telefonda klavyedeki "Git"). İki kutu da doluysa Sınavı Aç; yalnızca anahtar
// yazılıysa (Sınav ID boş) TG Denemeleri Hata Defteri açılır. Panel zaten açıksa Enter onu kapatmaz.
// Not: Sınavı Aç artık form gönderme düğmesi değil; tarayıcı Enter'ı her zaman ilk gönderme düğmesine
// bağladığı için ayrım ancak bu şekilde yapılabiliyor.
function enterIleAc(){
  let id = document.getElementById("sinavIdInput").value.trim(), anahtar = document.getElementById("anahtarInput").value.trim();
  if(anahtar && !id){
    let tg = document.getElementById("ekAcBtn");
    if(!tg.disabled && document.getElementById("ekPanel").hidden) tg.click();
    return;
  }
  listeGetir();
}
["sinavIdInput", "anahtarInput"].forEach(function(kimlik){
  document.getElementById(kimlik).addEventListener("keydown", function(e){
    if(e.key !== "Enter" || e.isComposing) return;
    e.preventDefault();
    enterIleAc();
  });
});
